 const bob=Math.round(Math.sin(now/450)*2),gx=68,gy=62+bob,pix=(x,y,w,h,color)=>{c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),w,h);};if(goblinReady){B.renderer.draw(c,goblin.sheet,goblin.cell,102,174+bob-(reveal&&tier===4?4:0),112,false);pix(143,gy+61,7,30,'#e7bc59');pix(138,gy+55,17,8,'#ffe09a');pix(149,gy+81,9,7,'#e7bc59');}else{pix(gx+12,gy+62,40,38,'#744c35');pix(gx+12,gy+94,14,16,'#302a25');pix(gx+40,gy+94,14,16,'#302a25');pix(gx-6,gy+12,14,28,'#76a653');pix(gx+54,gy+12,16,28,'#76a653');pix(gx+6,gy,50,58,'#93bb65');pix(gx+10,gy+4,42,12,'#adc87b');pix(gx+12,gy+25,12,10,'#e8e3bc');pix(gx+38,gy+25,12,10,'#e8e3bc');pix(gx+18,gy+26,5,reveal&&tier===4?3:8,'#182a21');pix(gx+38,gy+26,5,reveal&&tier===4?3:8,'#182a21');pix(gx+25,gy+34,12,10,'#72994d');pix(gx+18,gy+47,26,4,'#263e27');pix(gx+46,gy+66,28,10,'#93bb65');pix(gx+72,gy+61,8,28,'#e7bc59');pix(gx+67,gy+55,18,8,'#e7bc59');pix(gx+80,gy+80,9,7,'#f8dc82');}
 const x=196+Math.round(shake),y=112;pix(x-5,y-5,105,68,'#101912');pix(x,y,94,58,'#8d5330');pix(x+5,y+7,84,10,'#b9773d');pix(x+5,y+23,84,25,'#633a26');pix(x+10,y,10,58,'#d1a34e');pix(x+74,y,10,58,'#d1a34e');pix(x,y+49,94,9,'#c0964b');if(reveal){pix(x,y-34,94,17,'#805234');pix(x+5,y-37,84,6,'#d0a754');pix(x+9,y-30,10,14,'#d0a754');pix(x+75,y-30,10,14,'#d0a754');pix(x+5,y+2,84,13,'#142018');}else{pix(x-3,y-22,100,28,'#b67c41');pix(x+4,y-27,86,12,'#d5a15a');pix(x+8,y-24,11,32,'#e7bd65');pix(x+75,y-24,11,32,'#e7bd65');pix(x+37,y-2,22,22,'#e6bd60');pix(x+45,y+3,6,11,'#3c3224');}if(reveal){for(let i=0;i<(tier>=3?24:9);i++){const t=(age-.9+i*.07)%1.9,cx=x+47+Math.sin(i*7.3)*t*62,cy=y-15-t*60+t*t*35;pix(cx,cy,8,5,i%2?'#f7d276':'#ba8a38');pix(cx+2,cy-2,4,2,'#ffe6a2');}if(tier===4){pix(x+30,y-64,40,12,'#f3ca65');pix(x+30,y-76,8,16,'#f3ca65');pix(x+46,y-82,8,22,'#ffe69a');pix(x+62,y-76,8,16,'#f3ca65');}}
